from pathlib import Path
from PIL import Image
import base64,json
r=Path(__file__).parent
names=['close-start','close70-white','close-half','closed','grip-lift-white','turn','hug']
assets={n:r/'canonical-static-v1'/f'{n}.png' for n in names}
assets.update(airborne=r/'canonical-registered-v1/airborne-clean-v2.png',preland=r/'canonical-registered-v1/preland-no-stool-white-alpha.png',contact=r/'canonical-registered-v1/contact-skirt-restored-v3.png',stool=r/'canonical-registered-v1/stool-world-candidate-v2.png')
data={k:'data:image/png;base64,'+base64.b64encode(v.read_bytes()).decode() for k,v in assets.items()}
assets.update({'settle-bridge':r/'canonical-registered-v2/contact-settle-bridge-white-alpha.png','lap-release':r/'canonical-static-v2/lap-release.png','close-gap':r/'canonical-static-v2/close-gap.png'})
data={k:'data:image/png;base64,'+base64.b64encode(v.read_bytes()).decode() for k,v in assets.items()}
html='''<!doctype html><meta charset=utf-8><title>Relocation contact review — candidate</title><style>body{background:#182431;color:#e8eef5;font:14px system-ui;margin:24px}button{padding:8px;margin:4px}canvas{background:#26384b;max-width:100%;border:1px solid #789}p{max-width:900px}</style><h2>Relocation — actual-drawing / world-contact review</h2><p>INTERNAL CANDIDATE, not finished animation. Keypose cadence, stool perspective and source junctions remain review targets. Root translation below is desktop relocation, not pose synthesis. Character images never crossfade; stool opacity is a separate world layer.</p><button onclick="run('normal')">Lift / move / land</button><button onclick="run('early')">Early release before departure</button><button onclick="run('regrab')">Regrab before landing</button><button onclick="paused=!paused">Pause</button><button onclick="speed=speed===1?.35:1">Slow / normal</button><button onclick="step(-1)">Previous drawing</button><button onclick="step(1)">Next drawing</button><div id=status></div><canvas id=c width=800 height=580></canvas><script>const sources=DATA;const imgs={};for(const[k,v]of Object.entries(sources)){imgs[k]=new Image();imgs[k].src=v}const ctx=c.getContext('2d');let start=performance.now(),last=start,elapsed=0,paused=false,speed=1,mode='normal';const closure=['close-start','close70-white','close-half','close-gap','closed','grip-lift-white','turn','hug'];let steps=[];function add(f,d,x=40,y=32,old=0,next=0){steps.push({f,d,x,y,old,next})}function run(m){mode=m;steps=[];elapsed=0;paused=false;for(const f of closure)add(f,80);if(m==='early'){steps=steps.slice(0,4);for(const f of closure.slice(0,3).reverse())add(f,80);add('close-start',300);return}add('preland',75,48,24,1);add('airborne',100,70,8,.7);add('airborne',100,105,-4,.3);add('airborne',120,145,-8,0);add('airborne',120,185,-8,0);add('airborne',160,230,-4,0,.4);add('preland',90,230,16,0,1);if(m==='regrab'){add('airborne',100,244,0,0,.6);add('airborne',160,266,-8,0,.2);add('airborne',200,280,-8);return}add('contact',90,230,32,0,1);add('settle-bridge',90,230,32,0,1);add('hug',100,230,32);for(const f of ['turn','grip-lift-white','closed'])add(f,90,230,32);add('lap-release',350,230,32)}run('normal');function step(delta){let acc=0,i=0;for(;i<steps.length;i++){if(elapsed<acc+steps[i].d)break;acc+=steps[i].d}i=Math.max(0,Math.min(steps.length-1,i+delta));elapsed=steps.slice(0,i).reduce((s,f)=>s+f.d,0)+.1;paused=true}function draw(t){if(!paused)elapsed+=(t-last)*speed;last=t;const total=steps.reduce((s,f)=>s+f.d,0);let a=0,index=steps.length-1;for(let i=0;i<steps.length;i++){a+=steps[i].d;if(elapsed<a){index=i;break}}let f=steps[index];if(elapsed>=total)paused=true;ctx.clearRect(0,0,800,580);ctx.strokeStyle='#7b91a6';ctx.beginPath();ctx.moveTo(0,535);ctx.lineTo(800,535);ctx.stroke();if(f.old){ctx.globalAlpha=f.old;ctx.drawImage(imgs.stool,40,32)}if(f.next){ctx.globalAlpha=f.next;ctx.drawImage(imgs.stool,230,32)}ctx.globalAlpha=1;if(imgs[f.f].complete){let prior=steps.slice(0,index).reduce((s,q)=>s+q.d,0),q=steps[Math.min(index+1,steps.length-1)],u=Math.max(0,Math.min(1,(elapsed-prior)/f.d)),move=f.f==='airborne'||f.f==='preland';ctx.drawImage(imgs[f.f],move?f.x+(q.x-f.x)*u:f.x,move?f.y+(q.y-f.y)*u:f.y)};document.getElementById('status').textContent=mode+' | '+f.f+' | frame '+(index+1)+'/'+steps.length+' | '+Math.round(Math.min(elapsed,total))+' ms / '+total+' ms';requestAnimationFrame(draw)}requestAnimationFrame(draw);</script>'''.replace('DATA',json.dumps(data))
(r/'reviews/world-contact-review-v3.html').write_text(html)
(r/'reviews/world-contact-assets-v3.json').write_text(json.dumps({'stage':'keyposes','warning':'internal scene integration candidate only; no smoothness/contact acceptance','assets':{k:str(v.relative_to(r)) for k,v in assets.items()},'worldAnchorOld':[40,32],'worldAnchorNew':[230,32]},indent=2))
